package calc

func tak(x, y, z int64) int64 {
	if y < x {
		return tak(tak(x-1, y, z), tak(y-1, z, x), tak(z-1, x, y))
	}
	return z
}

package calc

import "testing"

func TestTak(t *testing.T) {
	if got := tak(6, 4, 2); got != 3 {
		t.Errorf("tak(6, 4, 2) = %d, want 3", got)
	}
	if got := tak(12, 8, 4); got != 5 {
		t.Errorf("tak(12, 8, 4) = %d, want 5", got)
	}
	if got := tak(1, 2, 3); got != 3 {
		t.Errorf("tak(1, 2, 3) = %d, want 3", got)
	}
}
